                        rj = routes[j]

                        def remove_delta(route, pos, node):
                            if len(route) == 1:
                                return -(d(depot, node) + d(node, depot))
                            if pos == 0:
                                return -(d(depot, node) + d(node, route[1]) - d(depot, route[1]))
                            if pos == len(route) - 1:
                                return -(d(route[-2], node) + d(node, depot) - d(route[-2], depot))
                            x = route[pos - 1]
                            y = route[pos + 1]
                            return -(d(x, node) + d(node, y) - d(x, y))

                        delta = remove_delta(ri, pi, a) + remove_delta(rj, pj, b)
                        # insert b into ri at pi, a into rj at pj (with adjusted positions)
                        rtmp = ri[:pi] + ri[pi + 1:]
                        delta += insertion_gain(rtmp, pi, b)
                        stmp = rj[:pj] + rj[pj + 1:]
                        delta += insertion_gain(stmp, pj, a)

                        if delta < best_delta:
                            best_delta = delta
                            best_move = ("swap", i, pi, j, pj, a, b)
        return best_move, best_delta

    # Improve iteratively
    improved = True
    while improved:
        improved = False

        # intra-route 2-opt
        for idx in range(len(routes)):
            new_r, changed = two_opt_route(routes[idx])
            if changed:
                routes[idx] = new_r
                improved = True

        # relocate / swap
        loads = [route_demand(r) for r in routes]

        move, delta = try_relocate(routes, loads)
        if move is not None and delta < -1e-12:
            _, i, pi, j, pj, node = move
            routes[i].pop(pi)
            loads[i] -= demand_map.get(node, 0)
            routes[j].insert(pj, node)
            loads[j] += demand_map.get(node, 0)
            if len(routes[i]) == 0:
                routes.pop(i)
                loads.pop(i)
            improved = True
            continue

        move, delta = try_swap(routes, loads)
        if move is not None and delta < -1e-12:
            _, i, pi, j, pj, a, b = move
            routes[i][pi] = b
            routes[j][pj] = a
            improved = True
            continue

    # Final cleanup: remove empty routes if any
    routes = [r for r in routes if r]

    return routes
